      "content": "{\n  \"name\": \"dsh-pet-remielle\",\n  \"version\": \"0.4.7\",\n  \"description\": \"蕾米埃尔（Remielle）桌宠 for DeepSeek Harness (DSH): session-event-driven sticker pet with status bubbles, SSE live updates, and a desktop floating window\",\n  \"private\": false,\n  \"type\": \"module\",\n  \"main\": \"src/index.js\",\n  \"exports\": {\n    \".\": \"./src/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./protocol\": \"./src/protocol.js\",\n    \"./reducer\": \"./src/pet-reducer.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"src/\",\n    \"lib/client.js\",\n    \"assets/\",\n    \"scripts/\",\n    \"test/\",\n    \"cordis.patch.yml\",\n    \"NOTICE\",\n    \"README.md\"\n  ],\n  \"engines\": {\n    \"node\": \">=22.19\",\n    \"dsh\": \">=0.1.2-alpha.1 <0.3.0-0\"\n  },\n  \"scripts\": {\n    \"build:client\": \"node scripts/build-client.mjs\",\n    \"generate\": \"node scripts/build-client.mjs\",\n    \"prepublishOnly\": \"node scripts/build-client.mjs\",\n    \"version\": \"node scripts/build-client.mjs && git add lib/client.js\",\n    \"pretest\": \"node scripts/build-client.mjs\",\n    \"test\": \"node --test --test-timeout=10000 \\\"test/*.test.js\\\"\",\n    \"pretest:platform\": \"node scripts/build-client.mjs\",\n    \"test:platform\": \"node --test --test-timeout=10000 test/platform/electron-fetch.test.js test/platform/pet-window-paths.integration.test.js test/platform/self-update.integration.test.js test/platform/desktop-window.test.js\",\n    \"check\": \"node --check lib/client.js && node --check src/index.js && node --check src/local-access.js && node --check src/pet-reducer.js && node --check src/session-order.cjs && node --check src/gif-frame.cjs && node --check src/bubble-title.cjs && node --check src/markdown.cjs && node --check src/turn-watchdog.js && node --check src/protocol.js && node --check src/status-copy.js && node --check src/pets.js && node --check src/self-update.js && node --check src/desktop-window.js && node --check src/electron-fetch.mjs && node --check src/pet-window.cjs && node --check src/pet-preload.cjs && node --check src/pet-window-paths.cjs && node --check src/pet-tip.cjs && node --check src/balance.js && node --check src/balance-widget.js && node --check src/holidays.js && node --check scripts/build-client.mjs\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.4\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [],\n      \"platform\": \"web\"\n    }\n  },\n  \"license\": \"MIT\",\n  \"os\": [\n    \"win32\",\n    \"darwin\",\n    \"linux\"\n  ],\n  \"cpu\": [\n    \"x64\",\n    \"arm64\"\n  ],\n  \"author\": \"dsh-pet-remielle contributors\",\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"deepseek\",\n    \"plugin\",\n    \"pet\",\n    \"desktop-pet\",\n    \"remielle\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/Gin-7/dsh-pet-remielle.git\"\n  }\n}\n"
    },
