ull\n      const readPetView = async () => {\n        if (petViewHtml) return petViewHtml\n        petViewHtml = await readFile(new URL('../src/pet-view.html', import.meta.url), 'utf8')\n        return petViewHtml\n      }\n      let balanceWidgetJs = null\n      const readBalanceWidget = async () => {\n        if (balanceWidgetJs) return balanceWidgetJs\n        balanceWidgetJs = await readFile(new URL('../src/balance-widget.js', import.meta.url), 'utf8')\n        return balanceWidgetJs\n      }\n      let sessionOrderJs = null\n      const readSessionOrder = async () => {\n        if (sessionOrderJs) return sessionOrderJs\n        sessionOrderJs = await readFile(new URL('../src/session-order.cjs', import.meta.url), 'utf8')\n        return sessionOrderJs\n      }\n      let petTipJs = null\n      const readPetTip = async () => {\n        if (petTipJs) return petTipJs\n        petTipJs = await readFile(new URL('../src/pet-tip.cjs', import.meta.url), 'utf8')\n        return petTipJs\n      }\n      let gifFrameJs = null\n      const readGifFrame = async () => {\n        if (gifFrameJs) return gifFrameJs\n        gifFrameJs = await readFile(new URL('../src/gif-frame.cjs', import.meta.url), 'utf8')\n        return gifFrameJs\n      }\n      let bubbleTitleJs = null\n      const readBubbleTitle = async () => {\n        if (bubbleTitleJs) return bubbleTitleJs\n        bubbleTitleJs = await readFile(new URL('../src/bubble-title.cjs', import.meta.url), 'utf8')\n        return bubbleTitleJs\n      }\n\n      // 单条路由注册失败（例如下游插件已占用同一路径）不能拖垮整张表：逐条隔离，\n      // 失败只记日志并跳过该条，其余端点照常注册。\n      const registerRoute = (route) => {\n        try {\n          return httpCtx.webServer.register(route)\n        } catch (error) {\n          logger.error?.(`dsh-pet-remielle: 路由注册失败 ${route?.path ?? '?'}：${String(error)}`)\n          return () => {}\n        }\n      }\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: CONFIG_ENDPOINT, handler: createConfigHandler(settings) }),\n        'dsh-pet-remielle: local settings endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: STATE_ENDPOINT, handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          jsonResponse(res, 200, serveState())\n        } }),\n        'dsh-pet-remielle: local state endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({\n          kind: 'exact',\n          path: COMPLETION_ACK_ENDPOINT,\n          handler: createCompletionAckHandler({\n            acknowledge: (sessionId, opts) => {\n              pulse = applyCompletionAck(completionQueue, pulse, sessionId, opts)\n              subagentSessionIds.delete(sessionId)\n            },\n            broadcast: () => hub.broadcast(),\n          }),\n        }),\n        'dsh-pet-remielle: completion notification acknowledgement',\n      )\n      httpCtx.effect(\n        () => registerRoute({\n          kind: 'exact',\n          path: SESSION_OPEN_ENDPOINT,\n          handler: createSessionOpenHandler({\n            notify: (payload) => {\n              const delivered = hub.notify(payload)\n              if (payload?.sessionId) dismissErrorIfNeeded(payload.sessionId)\n              return delivered\n            },\n            onUndelivered: (action) => pendingActions.stash(action),\n          }),\n        }),\n        'dsh-pet-remielle: desktop session open/approve bridge',\n      )\n      httpCtx.effect(\n        () => registerRoute({\n          kind: 'exact',\n          path: SESSION_CURRENT_ENDPOINT,\n          handler: createSessionCurrentHandler({\n            store: currentSessionStore,\n            accept: (sessionId, { changed }) => {\n              dismissErrorIfNeeded(sessionId)\n              // 值变了就广播：桌面窗要靠快照里的 currentSessionId 才知道你在看哪个会话，\n              // 不广播它就得等下一次任意广播或自己的 5 秒轮询（绿点消失比网页端慢半拍）。\n              if (changed) hub.broadcast()\n            },\n          }),\n        }),\n        'dsh-pet-remielle: web client current-session uplink',\n      )\n      httpCtx.effect(\n        () => registerRoute({\n          kind: 'exact',\n          path: THEME_ENDPOINT,\n          handler: createThemeHandler({\n            accept: (theme, { changed }) => {\n              reportedHostTheme = theme\n              // 清除上报（空串）同样刷新时间戳：清除态本身也是有效状态\n              reportedHostThemeAt = Date.now()\n              // 值变了就广播：桌面悬浮窗靠快照里的 hostTheme 决定菜单/气泡配色，\n              // 宿主主题一换它得立刻跟上，否则两端会出现一段时间的水土不服。\n              if (changed) hub.broadcast()\n            },\n          }),\n        }),\n        'dsh-pet-remielle: web client host-theme uplink',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: BALANCE_ENDPOINT, handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          try {\n            const payload = await balanceService.getBalance(settings.get().usageMode)\n            jsonResponse(res, 200, payload)\n          } catch (err) {\n            jsonResponse(res, 200, { ok: false, code: 'ERROR', error: String((err && err.message) || err).slice(0, 200) })\n          }\n        } }),\n        'dsh-pet-remielle: balance endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: STREAM_ENDPOINT, handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          sseHeaders(res)\n          // 订阅者类型入 hub：?client=pet（桌宠窗口）不参与 delivered 计数，\n          // 否则它常驻订阅会让 session-action 永远“已送达”，暂存兜底成死代码。\n          const client = streamClientOf(req.url)\n          hub.add(res, { client })\n          // 无网页在线时点卡的动作在此重放：新网页订阅者握手即补收最新一条\n          // session-action。桌宠窗口会丢弃带 kind 的帧——跳过重放，防止\n          // 它断线重连时把暂存动作抢收吞掉。\n          if (client !== 'pet') {\n            const replay = pendingActions.take()\n            if (replay) {\n              try {\n                res.write(`data: ${JSON.stringify(replay)}\\n\\n`)\n              } catch {\n                // 客户端已断开：回滚暂存，动作留给下一个网页订阅者，\n                // 避免先 take 后 write 失败导致动作静默丢失。\n                pendingActions.stash(replay)\n              }\n            }\n          }\n        } }),\n        'dsh-pet-remielle: local state stream endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: PET_VIEW_ENDPOINT, handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          const html = await readPetView()\n          res.writeHead(200, {\n            'content-type': 'text/html; charset=utf-8',\n            'cache-control': 'no-store',\n          })\n          res.end(html)\n        } }),\n        'dsh-pet-remielle: pet window view',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: '/plugins/dsh-pet-remielle/balance-widget.js', handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          const js = await readBalanceWidget()\n          res.writeHead(200, {\n            'content-type': 'application/javascript; charset=utf-8',\n            'cache-control': 'no-store',\n          })\n          res.end(js)\n        } }),\n        'dsh-pet-remielle: balance bubble client script',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: '/plugins/dsh-pet-remielle/session-order.js', handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          const js = await readSessionOrder()\n          res.writeHead(200, {\n            'content-type': 'application/javascript; charset=utf-8',\n            'cache-control': 'no-store',\n          })\n          res.end(js)\n        } }),\n        'dsh-pet-remielle: shared bubble order script',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: '/plugins/dsh-pet-remielle/pet-tip.js', handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          const js = await readPetTip()\n          res.writeHead(200, {\n            'content-type': 'application/javascript; charset=utf-8',\n            'cache-control': 'no-store',\n          })\n          res.end(js)\n        } }),\n        'dsh-pet-remielle: shared pet tip script',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: '/plugins/dsh-pet-remielle/gif-frame.js', handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          const js = await readGifFrame()\n          res.writeHead(200, {\n            'content-type': 'application/javascript; charset=utf-8',\n            'cache-control': 'no-store',\n          })\n          res.end(js)\n        } }),\n        'dsh-pet-remielle: shared gif frame script',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: '/plugins/dsh-pet-remielle/bubble-title.js', handler: async (req, res) => {\n          if (!localOnly(req, res)) return\n          const js = await readBubbleTitle()\n          res.writeHead(200, {\n            'content-type': 'application/javascript; charset=utf-8',\n            'cache-control': 'no-store',\n          })\n          res.end(js)\n        } }),\n        'dsh-pet-remielle: shared bubble card script',\n      )\n      httpCtx.effect(\n        () => registerRoute({\n          kind: 'prefix',\n          path: DESKTOP_ENDPOINT,\n          handler: async (req, res) => {\n            if (!localOnly(req, res)) return\n            if (req.method !== 'POST') {\n              jsonResponse(res, 405, { ok: false, error: 'method not allowed (POST only)' })\n              return\n            }\n            let action = 'unknown'\n            try {\n              action = new URL(req.url, 'http://localhost').pathname.split('/').pop() || 'unknown'\n            } catch {\n              /* keep unknown */\n            }\n            if (action === 'start') startDesktop(true)\n            else if (action === 'stop') stopDesktop('in-page menu')\n            else if (action === 'confirm-download') runDownload()\n            // cancel-download 分支自行响应后必须 return：落到末尾会二次\n            // jsonResponse → ERR_HTTP_HEADERS_SENT（实测宿主日志反复告警）。\n            else if (action === 'cancel-download') { confirmSent = false; jsonResponse(res, 200, { ok: true }); return }\n            // 窗口主进程 show() 之后回报：宿主据此才把 desktopActive 置 true（隐藏页面宠物）。\n            else if (action === 'ready') { markDesktopReady(); jsonResponse(res, 200, { ok: true, desktopActive }); return }\n            else {\n              jsonResponse(res, 400, { ok: false, error: 'expected /desktop/start, /desktop/stop, /desktop/confirm-download, /desktop/cancel-download, or /desktop/ready' })\n              return\n            }\n            jsonResponse(res, 200, { ok: true, desktopActive })\n          },\n        }),\n        'dsh-pet-remielle: desktop window start/stop/confirm-download',\n      )\n      httpCtx.effect(\n        () => registerRoute({\n          kind: 'prefix',\n          path: PETS_ENDPOINT,\n          handler: createPetsHandler({ settings, refreshRegistry }),\n        }),\n        'dsh-pet-remielle: pets registry endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({\n          kind: 'prefix',\n          path: ASSETS_PREFIX,\n          handler: createAssetsHandler(petsRoot),\n        }),\n        'dsh-pet-remielle: pet sticker assets',\n      )\n      // ---- self-update routes (version check + one-click update) ----\n      // 一键更新会替换插件目录内的文件：先停掉桌宠窗并等进程退出——\n      // electron.exe 从 vendor/ 目录内运行时会锁住文件，导致 pnpm/git EPERM\n      setSelfUpdateHooks({\n        stopDesktopWindow: async (reason = 'self-update') => {\n          const w = desktop\n          await w?.stop(reason)\n          if (w && desktopActive) { desktopActive = false; hub.broadcast() }\n        },\n        // 更新成功后收尾：包内下载的 Electron 运行时已被 pnpm 替换掉，\n        // 桌面模式继续开着会让重启后“双端皆无宠物”。自动切回网页宠物；\n        // 返回的说明文字会展示在更新卡片里。\n        onUpdateSuccess: () => {\n          if (settings.get().desktopMode !== false) {\n            void settings.update({ desktopMode: false })\n            return '检测到桌面悬浮模式：其 Electron 运行时随更新被移除，已自动切回网页宠物；重启后可重新开启（将重新下载运行时）。'\n          }\n          return null\n        },\n      })\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: CHECK_ENDPOINT, handler: checkHandler }),\n        'dsh-pet-remielle: version check endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: UPDATE_ENDPOINT, handler: updateHandler }),\n        'dsh-pet-remielle: one-click update endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: PROGRESS_ENDPOINT, handler: progressHandler }),\n        'dsh-pet-remielle: live update progress endpoint',\n      )\n      httpCtx.effect(\n        () => registerRoute({ kind: 'exact', path: INFO_ENDPOINT, handler: infoHandler }),\n        'dsh-pet-remielle: install info endpoint',\n      )\n      httpCtx.effect(() => () => {\n        unwatchDesktop()\n        stopDesktop('dsh-host-stop')\n        // 宿主退出时终止进行中的 pnpm/git：孤儿进程会把 node_modules 改成\n        // 半成品，下一次启动插件加载直接崩溃\n        killActiveUpdate()\n      })\n    })\n  }\n\n  ctx.effect(() => () => {\n    clearInterval(watchdogTimer)\n    offEvent?.()\n    offDisposed?.()\n    unwatch()\n    // 告别帧（issue #34）：此刻 SSE 连接还活着、路由尚未被宿主注销，先推\n    // plugin-gone 让页面里所有客户端立即自拆（毫秒级消失），再关流。推不出去\n    // 也没关系——客户端还有 404 藏匿 + 连击自毁 + bootId 代际检测三层兜底。\n    try { hub.notify({ kind: 'plugin-gone' }) } catch { /* dispose 期连接可能已不可用 */ }\n    hub.close()\n  })\n}\n\nexport function apply(ctx, config = {}) {\n  if (typeof ctx.inject === 'function') {\n    // settings 是可选能力：未就绪时不能把整个插件（含全部路由）一起 gate 掉。\n    // 正常路径仍等 settings 就绪；超时后按本地配置 scope 降级挂载。\n    let mounted = false\n    const start = (settingsCtx) => {\n      if (mounted) return\n      mounted = true\n      try {\n        mount(settingsCtx ?? ctx, config, ctx)\n      } catch (err) {\n        // 降级路径（settings 未就绪，或宿主缺其它可选服务）会走到这里：异常绝不能\n        // 落进 setTimeout 变成未捕获异常——那会比 base 的「静默不挂载」更糟。\n        ctx.logger?.error?.(`dsh-pet-remielle: 挂载失败 ${err?.message ?? err}`)\n      }\n    }\n    ctx.inject(['settings'], (settingsCtx) => start(settingsCtx))\n    const timer = setTimeout(() => {\n      if (mounted) return\n      ctx.logger?.warn?.('dsh-pet-remielle: settings 服务未就绪，降级为本地配置挂载')\n      start(ctx)\n    }, 5000)\n    timer.unref?.()\n    return\n  }\n  mount(ctx, config)\n}\n\nexport {\n  PetMessageKind,\n  PetReducer,\n  PetState,\n}\n"
