      "path": "src/pet-reducer.js",
      "content": "/**\n * Pure, testable state machine that turns DSH session events into pet\n * messages (state / pulse / task). The shape is:\n *\n *  - every rendered message carries a `mood` (remielle sticker id), derived\n *    from state + phase (THINKING -> '04', tools -> '02', ...);\n *  - assistant output streaming is tracked as a THINKING phase 'streaming'\n *    so the \"绘制中\" sticker shows while text is being written;\n *  - SUCCESS / ERROR are transient PULSE overlays with a TTL (the browser\n *    client shows them until the deadline, then falls back to durable state).\n */\n\nimport { createRequire } from 'node:module'\nimport {\n  PetMessageKind,\n  PetState,\n  createMessage,\n} from './protocol.js'\nimport {\n  activityCopy,\n  activityStage,\n  statusCopy,\n  taskCopy,\n} from './status-copy.js'\n\nconst { compareSessions } = createRequire(import.meta.url)('./session-order.cjs')\n\nconst statePriority = Object.freeze({\n  [PetState.WAITING]: 60,\n  [PetState.ERROR]: 50,\n  [PetState.WORKING]: 30,\n  [PetState.THINKING]: 20,\n  [PetState.IDLE]: 0,\n  [PetState.DISCONNECTED]: -1,\n})\n\nconst ASK_USER_TOOL = 'ask_user_question'\nconst PLAN_REVIEW_TOOL = 'exit_plan_mode'\n\nfunction toolActivity(name) {\n  const value = String(name || '').toLowerCase()\n  if (/search|grep|find|glob|web|read|fetch|open/.test(value)) return 'searching'\n  if (/write|edit|patch|replace|create|move|delete/.test(value)) return 'editing'\n  if (/test|check|lint|build|verify/.test(value)) return 'testing'\n  if (/shell|bash|exec|command|terminal|powershell/.test(value)) return 'commanding'\n  return 'using-tool'\n}\n\nfunction sessionIdOf(session) {\n  return String(session?.header?.id ?? session?.id ?? 'unknown-session')\n}\n\nexport function isSubagent(session) {\n  return session?.header?.origin === 'subagent'\n    || Number(session?.header?.delegationDepth ?? 0) > 0\n}\n\nfunction cleanProjectName(value) {\n  const text = String(value ?? '').trim()\n  if (!text) return undefined\n  const pathParts = text.split(/[\\\\/]/u).filter(Boolean)\n  const candidate = pathParts.length > 1 ? pathParts.at(-1) : text\n  return candidate.replace(/\\s+/gu, ' ').slice(0, 40) || undefined\n}\n\n/** 标题规范化：DSH 写入 `session/title` 时已按 `maxTitleBytes` 规范化，这里只做\n *  trim 与空值判定，不再额外截断（与 DSH 的 `foldSessionTitle` 口径一致）。 */\nfunction normalizeTitle(value) {\n  return String(value ?? '').trim()\n}\n\n/**\n * 现有会话的标题：先认实时 `session/title` 事件，再问注入的 `resolveTitle`。\n *\n * 恢复运行的老会话（DSH 重启后）不会重放标题事件，唯一正确的读法是宿主的\n * `sessionTitle` 服务——它自己按会话日志折出最新标题。reducer 因此不再直接翻\n * 会话日志：2026-09-09 起 DSH 把同步读事件（`snapshotEvents`/`eventAt`/\n * `ownEvents`）标为弃用并禁止新增调用，而 `sessionTitle.get()` 是官方替代。\n * `resolveTitle` 由宿主侧注入；返回 null 表示「标题服务当前不可用」（未安装、\n * 停用或被隔离），与 undefined「服务在、但该会话还没有标题」区分：前者不置\n * titleFolded，后续事件再试一次；后者折过一次就够，避免每条事件都让服务折日志。\n */\nfunction conversationTitleOf(session, event, resolveTitle) {\n  if (event?.type === 'session/title') {\n    const text = normalizeTitle(event?.data?.title)\n    if (text) return text\n  }\n  if (typeof resolveTitle !== 'function') return null\n  try {\n    const resolved = resolveTitle(session)\n    if (resolved === null) return null\n    return normalizeTitle(resolved) || undefined\n  } catch {\n    return null // 服务被隔离时访问会抛错，不能冒到事件热路径\n  }\n}\n\n/**\n * 气泡第二行的项目名：宿主把 cwd 只挂在 `SessionHeader` 上——`Session` 类本身没有\n * `cwd`/`title`/`name`/`context`，header 也只有 version/id/createdAt/cwd/... 且是\n * 冻结的创建元数据；会话事件 payload 里没有 cwd（`EpochHeader` / `RequestContext`\n * 都不含），所以这是唯一来源。\n */\nfunction projectNameOf(session) {\n  return cleanProjectName(session?.header?.cwd)\n}\n\nfunction progressOf(todos) {\n  if (!Array.isArray(todos) || todos.length === 0) return undefined\n  const completed = todos.filter((todo) => ['completed', 'complete', 'done'].includes(todo?.status)).length\n  const currentIndex = todos.findIndex((todo) => todo?.status === 'in_progress')\n  return {\n    completed,\n    total: todos.length,\n    current: currentIndex >= 0 ? currentIndex + 1 : undefined,\n  }\n}\n\nfunction clipLine(text, max = 80) {\n  const value = String(text ?? '').replace(/\\s+/gu, ' ').trim()\n  if (!value) return ''\n  return value.length > max ? `${value.slice(0, max - 1)}…` : value\n}\n\nfunction parseToolArgs(raw) {\n  if (raw && typeof raw === 'object') return raw\n  try { return JSON.parse(String(raw ?? '')) } catch { return null }\n}\n\nfunction approvalReason(reason) {\n  let value = String(reason ?? '').replace(/\\s+/gu, ' ').trim()\n  if (!value) return ''\n  // 去掉 auto-review 的固定前缀：`Auto review denied tool \"ops_bash\": 真正原因`。\n  // 这段前缀在气泡里只挤占空间，工具名也不提供判断信息（冒号之后才是原因）；\n  // 只有前缀、没有原因时返回空串，交给 approvalContent 回落到命令/描述。\n  // 不依赖具体工具名与动词：任何以 Auto review 开头的机器前缀，只保留第一个冒号\n  // （半角或全角）之后的内容；没有冒号（如「Auto review denied tool \"x\"」或中文\n  // 「Auto review 拒绝了此调用。」）就整段丢弃，交给下面的命令/描述回落。\n  const autoReview = value.match(/^auto review\\b[^:：]*[:：]\\s*(.*)$/iu)\n  if (autoReview) value = autoReview[1].trim()\n  else if (/^auto review\\b/iu.test(value)) value = ''\n  if (!value) return ''\n  const match = value.match(/^escalate sandbox to \\S+:\\s*(.+)$/iu)\n  return match ? match[1].trim() : value\n}\n\nfunction approvalContent(toolName, reason, argsRaw) {\n  const why = clipLine(approvalReason(reason))\n  if (why) return why\n  const args = parseToolArgs(argsRaw)\n  if (args && typeof args.justification === 'string' && args.justification.trim()) return clipLine(args.justification)\n  if (args && typeof args.command === 'string' && args.command.trim()) return clipLine(args.command)\n  if (args && typeof args.description === 'string' && args.description.trim()) return clipLine(args.description)\n  return clipLine(toolName) || '等待确认'\n}\n\nfunction planReviewContent(argsRaw) {\n  const args = parseToolArgs(argsRaw)\n  const markdown = String(args?.plan ?? '').replace(/\\r\\n?/g, '\\n').trim()\n  if (!markdown) return '计划待审'\n  const heading = markdown.match(/^#\\s+(.+)$/mu)\n  if (heading) return clipLine(heading[1]) || '计划待审'\n  const paragraph = markdown.split(/\\n\\s*\\n/u).map((part) => part.trim()).find(Boolean)\n  return clipLine(paragraph || markdown) || '计划待审'\n}\n\nfunction detailFor(record, stage = record.payload.stage) {\n  const approval = record.waits?.find((wait) => wait.kind === 'approval')\n  if (approval) {\n    const parts = []\n    if (record.project) parts.push(record.project)\n    parts.push(approval.payload.preview || approval.payload.toolName || '等待确认')\n    return parts.join(' · ')\n  }\n  const planReview = record.waits?.find((wait) => wait.kind === 'plan-review')\n  if (planReview) {\n    const parts = []\n    if (record.project) parts.push(record.project)\n    parts.push('计划待审')\n    if (planReview.payload.preview && planReview.payload.preview !== '计划待审') parts.push(planReview.payload.preview)\n    return parts.join(' · ')\n  }\n  const parts = []\n  if (record.project) parts.push(record.project)\n  if (record.progress?.total) parts.push(`已完成 ${record.progress.completed}/${record.progress.total} 步`)\n  if (record.task) parts.push(record.task)\n  else if (stage) parts.push(stage)\n  return parts.join(' · ') || stage || 'DSH 任务'\n}\n\n/** Remielle sticker for the current durable state + phase. */\nexport function moodFor(state, phase) {\n  // 流式输出（正在写回复）→ 绘制中；其它思考 → 思考中\n  if (state === PetState.THINKING && phase === 'streaming') return '01'\n  if (state === PetState.THINKING) return '04'\n  if (state === PetState.WAITING) return '05'\n  if (state === PetState.IDLE) return '06'\n  if (state === PetState.DISCONNECTED) return '06'\n  // WORKING (tool busy) and ERROR both show as \"摸鱼中\".\n  return '02'\n}\n\nexport class PetReducer {\n  constructor({ includeSubagents = false, resolveTitle } = {}) {\n    this.includeSubagents = includeSubagents\n    this.resolveTitle = typeof resolveTitle === 'function' ? resolveTitle : undefined\n    this.sessions = new Map()\n    this.clock = 0\n    this.selectedSessionId = undefined\n    this.outputSignature = undefined\n  }\n\n  setIncludeSubagents(value) {\n    const includeSubagents = value === true\n    if (includeSubagents === this.includeSubagents) return []\n    this.includeSubagents = includeSubagents\n    if (!includeSubagents) {\n      for (const [sessionId, record] of this.sessions) {\n        if (record.subagent) this.sessions.delete(sessionId)\n      }\n    }\n    return this.#render()\n  }\n\n  handle(session, event) {\n    if (!event || typeof event.type !== 'string') return []\n    const subagent = isSubagent(session)\n    if (!this.includeSubagents && subagent) return []\n\n    const sessionId = sessionIdOf(session)\n    const record = this.#record(sessionId)\n    record.subagent = subagent\n    record.lastSeq = Number(event.seq ?? record.lastSeq)\n    record.project = projectNameOf(session) ?? record.project\n    // 标题来源有两个：实时 session/title 事件，或宿主 sessionTitle 服务（覆盖\n    // 恢复会话）。后者每个会话只问一次（titleFolded 置位）——它是每条事件都会\n    // 走的热路径，反复问没有意义；改名会派发新的 session/title 事件，仍走第一支。\n    // 宿主侧 readSessionTitle 则每帧重试，两条口径刻意不同。\n    if (event.type === 'session/title' || !record.titleFolded) {\n      const nextTitle = conversationTitleOf(session, event, this.resolveTitle)\n      // null = 标题服务当前不可用：保持 titleFolded=false，下一条事件再试；\n      // 服务晚挂载/恢复后，标题仍能补上，而不是永久为空。\n      if (nextTitle !== null) {\n        record.title = nextTitle ?? record.title\n        record.titleFolded = true\n      }\n    }\n\n    switch (event.type) {\n      case 'turn/start':\n        record.turnActive = true\n        record.openTools.clear()\n        record.askTools.clear()\n        record.planTools.clear()\n        record.waits.length = 0\n        record.savedState = undefined\n        record.savedPayload = undefined\n        record.task = undefined\n        record.progress = undefined\n        this.#update(record, PetState.THINKING, {\n          phase: 'turn-start',\n          stage: '准备阶段',\n          message: statusCopy('preparing', event.seq),\n        })\n        return this.#render()\n\n      case 'step/start':\n        if (!record.turnActive || record.openTools.size > 0) return []\n        this.#update(record, PetState.THINKING, {\n          phase: 'step-start',\n          stage: '分析阶段',\n          message: statusCopy('thinking', event.seq),\n        })\n        return this.#render()\n\n      case 'assistant/chunk': {\n        if (!record.turnActive || record.openTools.size > 0) return []\n        const chunkType = String(event.data?.chunk?.type ?? 'text-delta')\n        if (chunkType === 'reasoning-delta') {\n          // 思考块（推理中）→ 思考中 04\n          this.#update(record, PetState.THINKING, {\n            phase: 'think',\n            stage: '推理阶段',\n            message: statusCopy('thinking', event.seq),\n          })\n        } else if (chunkType === 'tool-call-delta') {\n          // 工具调用流式帧 → 摸鱼中 02（随后的 tool/call 事件继续/确认）\n          this.#update(record, PetState.WORKING, {\n            phase: 'tool-call',\n            stage: '调用工具',\n            message: statusCopy('working', event.seq),\n          })\n        } else {\n          // text-delta（默认）：真正输出 → 绘制中 01\n          this.#update(record, PetState.THINKING, {\n            phase: 'streaming',\n            stage: '输出阶段',\n            message: statusCopy('streaming', event.seq),\n          })\n        }\n        return this.#render()\n      }\n\n      case 'assistant/message':\n        if (!record.turnActive || record.openTools.size > 0) return []\n        this.#update(record, PetState.THINKING, {\n          phase: 'streaming',\n          stage: '输出阶段',\n          message: statusCopy('streaming', event.seq),\n        })\n        return this.#render()\n\n      case 'tool/call': {\n        const callId = String(event.data?.callId ?? `seq-${String(event.seq ?? 'unknown')}`)\n        const name = String(event.data?.name ?? 'tool')\n        record.openTools.set(callId, { name, args: event.data?.arguments })\n        // 计划审核通过 user-questions waterfall 呈现，不会发 approval/asked；\n        // 但 exit_plan_mode 的 tool/call 是它进入等待期的稳定宿主信号。\n        if (name === PLAN_REVIEW_TOOL) {\n          record.planTools.add(callId)\n          this.#enterWait(record, {\n            kind: 'plan-review',\n            id: callId,\n            payload: {\n              phase: 'plan-review',\n              stage: '计划待审',\n              toolName: name,\n              preview: planReviewContent(event.data?.arguments),\n              message: '计划待审',\n            },\n          })\n          return this.#render()\n        }\n        // Asking the human a question is a \"waiting\" state, not \"摸鱼中\".\n        if (name === ASK_USER_TOOL) {\n          record.askTools.add(callId)\n          this.#enterWait(record, {\n            kind: 'ask',\n            id: callId,\n            payload: {\n              phase: 'ask',\n              stage: '等待回答',\n              toolName: name,\n              message: statusCopy('waiting', event.seq),\n            },\n          })\n          return this.#render()\n        }\n        const activity = toolActivity(name)\n        this.#update(record, PetState.WORKING, {\n          phase: 'tool-call',\n          activity,\n          stage: activityStage(activity),\n          toolName: name,\n          message: activityCopy(activity, event.seq),\n        })\n        return this.#render()\n      }\n\n      case 'tool/result':\n        return this.#toolResult(record, event)\n\n      case 'todo/write':\n        return this.#todo(record, event)\n\n      case 'approval/asked': {\n        // Waiting for the human to confirm/deny a tool approval.\n        const toolName = String(event.data?.toolName ?? 'tool')\n        const approvalId = String(event.data?.id ?? `seq-${String(event.seq ?? 'unknown')}`)\n        const callId = event.data?.callId ? String(event.data.callId) : ''\n        let argsRaw\n        if (callId && record.openTools.has(callId)) argsRaw = record.openTools.get(callId).args\n        else {\n          for (const entry of record.openTools.values()) {\n            if (entry.name === toolName) { argsRaw = entry.args; break }\n          }\n        }\n        this.#enterWait(record, {\n          kind: 'approval',\n          id: approvalId,\n          payload: {\n            phase: 'approval',\n            stage: '等待确认',\n            toolName,\n            preview: approvalContent(toolName, event.data?.reason, argsRaw),\n            message: statusCopy('waiting', event.seq),\n          },\n        })\n        return this.#render()\n      }\n\n      case 'approval/decided':\n        // Approval resolved: restore whatever the pet was doing underneath.\n        this.#exitWait(record, 'approval', String(event.data?.id ?? ''))\n        return this.#render()\n\n      case 'turn/end':\n        return this.#turnEnd(record, event)\n\n      default:\n        return []\n    }\n  }\n\n  disposeSession(session) {\n    const sessionId = sessionIdOf(session)\n    const existed = this.sessions.delete(sessionId)\n    if (!existed) return []\n    return this.#render()\n  }\n\n  /**\n   * 打开该会话即已读：只收口耐久 ERROR（turn/end 失败），回 IDLE，牌叠不再渲染。\n   * WAITING（审批/提问）和工具报错脉冲不走这里。\n   */\n  dismissError(sessionId) {\n    const record = this.sessions.get(String(sessionId ?? ''))\n    if (!record || record.state !== PetState.ERROR) return []\n    this.#update(record, PetState.IDLE, {\n      phase: 'turn-end',\n      stage: '已停止',\n      message: statusCopy('stopped'),\n    })\n    return this.#render()\n  }\n\n  /**\n   * One renderable state per active or attention-needing session. IDLE and\n   * DISCONNECTED records remain internally tracked for primary-state fallback,\n   * but are omitted from the card deck so completed/stopped turns disappear.\n   * A SUCCESS pulse is emitted for every completed turn; the Host persists\n   * its reminder independently until the conversation is opened.\n   */\n  states() {\n    const out = []\n    for (const record of this.sessions.values()) {\n      if ([PetState.IDLE, PetState.DISCONNECTED].includes(record.state)) continue\n      out.push({\n        sessionId: record.id,\n        state: record.state,\n        mood: moodFor(record.state, record.payload.phase),\n        phase: record.payload.phase ?? '',\n        message: record.payload.message ?? '',\n        detail: detailFor(record),\n        project: record.project,\n        title: record.title,\n        task: record.task,\n        progress: record.progress,\n        // Only an unresolved approval wait may render the actionable ✓.\n        // Generic WAITING (ask_user_question) and ERROR must not inherit it.\n        approval: record.waits.some((wait) => wait.kind === 'approval'),\n        // 计划审核是独立的用户决策门，不复用普通审批或普通提问字段。\n        planReview: record.waits.some((wait) => wait.kind === 'plan-review'),\n        // 等待用户回答（ask_user_question）单独暴露，供气泡排序置于审批之下、完成之上。\n        ask: record.waits.some((wait) => wait.kind === 'ask'),\n        attention: record.state === PetState.WAITING || record.state === PetState.ERROR,\n        updatedAt: record.updatedAt,\n      })\n    }\n    out.sort((left, right) => compareSessions(left, right))\n    return out\n  }\n\n  #toolResult(record, event) {\n    const callId = String(event.data?.message?.source?.callId\n      ?? event.data?.message?.toolCallId\n      ?? event.data?.message?.callId\n      ?? event.data?.callId\n      ?? '')\n    const knownTool = callId ? record.openTools.has(callId) || record.askTools.has(callId) || record.planTools.has(callId) : false\n    if (!record.turnActive && !knownTool) return []\n    const wasAsk = callId ? record.askTools.has(callId) : false\n    const wasPlanReview = callId ? record.planTools.has(callId) : false\n    if (wasAsk) record.askTools.delete(callId)\n    if (wasPlanReview) record.planTools.delete(callId)\n    if (callId) record.openTools.delete(callId)\n    // An answered question or plan review ends the waiting state; restore what\n    // the pet was doing underneath (e.g. THINKING while streaming the answer).\n    if (wasAsk || wasPlanReview) {\n      this.#exitWait(record, wasPlanReview ? 'plan-review' : 'ask', callId)\n      return this.#render()\n    }\n    const next = record.openTools.size > 0 ? PetState.WORKING : PetState.THINKING\n    const nextPayload = {\n      phase: 'tool-result',\n      activity: next === PetState.WORKING\n        ? toolActivity(record.openTools.values().next().value?.name)\n        : undefined,\n      stage: next === PetState.WORKING\n        ? activityStage(toolActivity(record.openTools.values().next().value?.name))\n        : '整理阶段',\n      message: next === PetState.WORKING\n        ? activityCopy(toolActivity(record.openTools.values().next().value?.name), event.seq)\n        : statusCopy('result', event.seq),\n    }\n    this.#update(record, next, nextPayload)\n    if (!event.data?.error) return this.#render()\n\n    // 与成功路径对称：后台工具报错也发脉冲提示，不再被全局的\n    // WAITING/ERROR 锚点整体吞掉（锚点状态由脉冲的 resume* 字段恢复）\n    const selection = this.#select()\n    const pulse = createMessage(PetMessageKind.PULSE, {\n      sessionId: record.id,\n      sourceSeq: event.seq,\n      state: PetState.ERROR,\n      mood: moodFor(PetState.ERROR, 'tool-error'),\n      ttlMs: 3000,\n      resumeState: selection.record.state,\n      resumeMood: moodFor(selection.record.state, selection.record.payload.phase),\n      resumeMessage: selection.record.payload.message,\n      resumeDetail: detailFor(selection.record),\n      message: statusCopy('toolError', event.seq),\n      detail: detailFor(record),\n      errorCode: event.data.error.code,\n    })\n    if ([PetState.WAITING, PetState.ERROR].includes(selection.record.state)) {\n      return [...this.#render(selection), pulse]\n    }\n    this.#remember(selection)\n    return [pulse]\n  }\n\n  #todo(record, event) {\n    const todos = Array.isArray(event.data?.todos) ? event.data.todos : []\n    const current = todos.find((todo) => todo?.status === 'in_progress')\n      ?? todos.find((todo) => todo?.status === 'pending')\n    const progress = progressOf(todos)\n    if (!current?.content && !progress) return []\n    const nextTask = current?.content ? String(current.content) : record.task\n    const unchanged = nextTask === record.task\n      && progress?.completed === record.progress?.completed\n      && progress?.total === record.progress?.total\n    if (unchanged) return []\n    record.task = nextTask\n    record.progress = progress\n    record.updatedAt = ++this.clock\n    const selection = this.#select()\n    if (selection.record.id !== record.id) return this.#render(selection)\n    return [createMessage(PetMessageKind.TASK, {\n      sessionId: record.id,\n      sourceSeq: event.seq,\n      task: record.task,\n      progress: record.progress,\n      project: record.project,\n      message: taskCopy(record.task),\n      detail: detailFor(record, '执行阶段'),\n    })]\n  }\n\n  #turnEnd(record, event) {\n    record.turnActive = false\n    record.openTools.clear()\n    record.askTools.clear()\n    record.planTools.clear()\n    record.waits.length = 0\n    record.savedState = undefined\n    record.savedPayload = undefined\n    const kind = String(event.data?.reason?.kind ?? 'completed')\n\n    if (kind === 'blocked') {\n      this.#update(record, PetState.WAITING, {\n        phase: 'turn-end',\n        stage: '等待确认',\n        message: statusCopy('waiting', event.seq),\n      })\n      return this.#render()\n    }\n\n    if (kind === 'aborted') {\n      this.#update(record, PetState.IDLE, {\n        phase: 'turn-end',\n        stage: '已停止',\n        message: statusCopy('stopped', event.seq),\n      })\n      return this.#render()\n    }\n\n    if (kind === 'disposed') {\n      // 会话被销毁/回收（dsh-agent-loop 以 cancel({kind:'disposed'}) 终止轮次）：\n      // 静默回待机，不产出误导性“需要处理”错误卡；紧随其后的 session/disposed\n      // 会移除记录，这里只负责事件窗口内的过渡状态。\n      this.#update(record, PetState.IDLE, {\n        phase: 'turn-end',\n        stage: '已停止',\n        message: statusCopy('stopped', event.seq),\n      })\n      return this.#render()\n    }\n\n    if (kind !== 'completed') {\n      this.#update(record, PetState.ERROR, {\n        phase: 'turn-end',\n        stage: '需要处理',\n        reasonKind: kind,\n        message: kind === 'max-tokens'\n          ? statusCopy('limit', event.seq)\n          : statusCopy('error', event.seq),\n      })\n      return this.#render()\n    }\n\n    this.#update(record, PetState.IDLE, {\n      phase: 'turn-end',\n      stage: '已完成',\n      message: statusCopy('idle', event.seq),\n    })\n    const selection = this.#select()\n    const pulse = createMessage(PetMessageKind.PULSE, {\n      sessionId: record.id,\n      sourceSeq: event.seq,\n      state: PetState.SUCCESS,\n      mood: '03',\n      ttlMs: 5000,\n      resumeState: selection.record.state,\n      resumeMood: moodFor(selection.record.state, selection.record.payload.phase),\n      resumeMessage: selection.record.payload.message,\n      resumeDetail: detailFor(selection.record),\n      phase: 'turn-end',\n      message: statusCopy('success', event.seq),\n      detail: detailFor(record, '本轮已完成'),\n      project: record.project,\n      title: record.title,\n    })\n    if ([PetState.WAITING, PetState.ERROR].includes(selection.record.state)) {\n      return [...this.#render(selection), pulse]\n    }\n    this.#remember(selection)\n    return [pulse]\n  }\n\n  #record(sessionId) {\n    let record = this.sessions.get(sessionId)\n    if (record) return record\n    record = {\n      id: sessionId,\n      state: PetState.IDLE,\n      payload: { phase: 'session-created', message: '蕾米埃尔待机中~' },\n      turnActive: false,\n      openTools: new Map(),\n      askTools: new Set(),\n      planTools: new Set(),\n      waits: [],\n      savedState: undefined,\n      savedPayload: undefined,\n      task: undefined,\n      progress: undefined,\n      project: undefined,\n      title: undefined,\n      titleFolded: false,\n      subagent: false,\n      lastSeq: -1,\n      updatedAt: ++this.clock,\n    }\n    this.sessions.set(sessionId, record)\n    return record\n  }\n\n  #update(record, state, payload) {\n    record.state = state\n    record.payload = payload\n    record.updatedAt = ++this.clock\n  }\n\n  /** Enter an identified human wait, remembering what to restore later. */\n  #enterWait(record, wait) {\n    if (record.waits.length === 0) {\n      record.savedState = record.state\n      record.savedPayload = record.payload\n    }\n    const existing = record.waits.findIndex((entry) => entry.kind === wait.kind && entry.id === wait.id)\n    if (existing >= 0) record.waits.splice(existing, 1)\n    record.waits.push(wait)\n    record.state = PetState.WAITING\n    record.payload = this.#waitPayload(record)\n    record.updatedAt = ++this.clock\n  }\n\n  /** Resolve one identified wait and restore work only after all waits settle. */\n  #exitWait(record, kind, id) {\n    const index = record.waits.findIndex((wait) => wait.kind === kind && wait.id === id)\n    if (index < 0) return\n    record.waits.splice(index, 1)\n    record.updatedAt = ++this.clock\n    if (record.waits.length > 0) {\n      record.state = PetState.WAITING\n      record.payload = this.#waitPayload(record)\n      return\n    }\n    record.state = record.savedState ?? PetState.THINKING\n    record.payload = record.savedPayload ?? { phase: 'wait-end', message: '蕾米埃尔待机中~' }\n    record.savedState = undefined\n    record.savedPayload = undefined\n  }\n\n  #waitPayload(record) {\n    return record.waits.find((wait) => wait.kind === 'approval')?.payload\n      ?? record.waits.at(-1)?.payload\n      ?? { phase: 'wait-end', message: '蕾米埃尔待机中~' }\n  }\n\n  #select() {\n    const records = [...this.sessions.values()]\n    if (records.length === 0) {\n      return {\n        record: {\n          id: 'dsh-host',\n          state: PetState.IDLE,\n          payload: { phase: 'no-session', message: '蕾米埃尔待机中~' },\n          updatedAt: ++this.clock,\n        },\n      }\n    }\n    records.sort((left, right) => {\n      const priority = (statePriority[right.state] ?? 0) - (statePriority[left.state] ?? 0)\n      return priority || right.updatedAt - left.updatedAt || left.id.localeCompare(right.id)\n    })\n    return { record: records[0] }\n  }\n\n  #render(selection = this.#select()) {\n    const signature = this.#signature(selection.record)\n    if (signature === this.outputSignature) return []\n    this.#remember(selection)\n    return [createMessage(PetMessageKind.STATE, {\n      sessionId: selection.record.id,\n      state: selection.record.state,\n      mood: moodFor(selection.record.state, selection.record.payload.phase),\n      ...selection.record.payload,\n      task: selection.record.task,\n      progress: selection.record.progress,\n      project: selection.record.project,\n      title: selection.record.title,\n      detail: detailFor(selection.record),\n    })]\n  }\n\n  #remember(selection) {\n    this.selectedSessionId = selection.record.id\n    this.outputSignature = this.#signature(selection.record)\n  }\n\n  #signature(record) {\n    return [\n      record.id,\n      record.state,\n      record.payload.phase ?? '',\n      record.payload.activity ?? '',\n      record.payload.toolName ?? '',\n      record.payload.preview ?? '',\n      record.payload.message ?? '',\n      record.project ?? '',\n      record.task ?? '',\n      record.progress?.completed ?? '',\n      record.progress?.total ?? '',\n    ].join('|')\n  }\n}\n\nexport { statePriority, toolActivity }\n"
    },
    {
      "path": "src/turn-watchdog.js",
      "content": "/**\n * Turn-hang watchdog (host half) — 兜底「强行终止会话后永久卡在分析阶段」。\n *\n * 用户在 GUI 强杀会话时，DSH agent-loop 补写的 turn/end 既可能没有落盘、\n * 也不向 live 事件总线广播（仅冷读日志时 repair 补 turn/end{kind:'interrupted'}），\n * 插件侧只见事件流戛然而止，reducer 永远停在 THINKING（如 step/start 的\n * 「分析阶段」）。本模块只做纯判定并保持可单测：记录每个会话最近一次事件的\n * 时刻，配合 reducer.states() 扫描仍在 THINKING/WORKING 且超过阈值无任何\n * 事件的会话；WAITING/ERROR/IDLE 不判悬挂——审批与等待用户回答可以合法\n * 等待很久。命中后的收尾（合成 turn/end{kind:'aborted'}）由 index.js 接线，\n * 复用 reducer 现有的 aborted 分支回 IDLE「已停止」，不新增公开方法。\n */\n\n/** 正常流式期间 chunk 事件频繁，3 分钟无任何事件即视为 turn 悬挂。 */\nexport const TURN_STALL_THRESHOLD_MS = 180_000\n\n/** 看门狗扫描周期（index.js 里 setInterval 的间隔）。 */\nexport const TURN_WATCHDOG_INTERVAL_MS = 30_000\n\nfunction isStallProne(state) {\n  return state === 'THINKING' || state === 'WORKING'\n}\n\n/**\n * 创建看门狗。`now` 可注入以便单测；`tick` 只读不写，\n * 命中列表由调用方收尾（合成 turn/end）后逐个调用 `end` 移除条目。\n */\nexport function createTurnWatchdog({ thresholdMs = TURN_STALL_THRESHOLD_MS, now = Date.now } = {}) {\n  const lastSeenMs = new Map()\n  return {\n    /** 任一 session/event 到达时刷新该会话的活跃时间戳。 */\n    feed(sessionId) {\n      if (!sessionId) return\n      lastSeenMs.set(String(sessionId), now())\n    },\n    /** turn/end 或 session/disposed 后回合已收尾，条目随之移除。 */\n    end(sessionId) {\n      if (!sessionId) return\n      lastSeenMs.delete(String(sessionId))\n    },\n    /**\n     * 扫描 reducer.states() 快照，返回超阈值且仍处 THINKING/WORKING 的\n     * 会话 id 列表；未 feed 过或已 end 的会话天然不会命中。\n     */\n    tick(states, at = now()) {\n      const stalled = []\n      for (const entry of Array.isArray(states) ? states : []) {\n        const sessionId = String(entry?.sessionId ?? '')\n        const seen = lastSeenMs.get(sessionId)\n        if (seen === undefined) continue\n        if (!isStallProne(entry.state)) continue\n        if (at - seen < thresholdMs) continue\n        stalled.push(sessionId)\n      }\n      return stalled\n    },\n  }\n}\n"
    },
    {
      "path": "src/local-access.js",
      "content": "const LOOPBACK_HOST_RE = /^(127\\.0\\.0\\.1|localhost|\\[::1\\])(:\\d+)?$/\n\n/** 去掉 IPv4-mapped 前缀（::ffff:）与接口 zone id 后的地址文本。 */\nfunction bareAddress(address) {\n  if (typeof address !== 'string') return ''\n  const zone = address.indexOf('%')\n  const value = zone === -1 ? address : address.slice(0, zone)\n  return value.startsWith('::ffff:') ? value.slice('::ffff:'.length) : value\n}\n\nexport function isLoopback(address) {\n  const value = bareAddress(address)\n  return value === '127.0.0.1' || value === '::1'\n}\n\n/** 绑定字面量在 Host 头里的权威形式；IPv6 文本带方括号。 */\nfunction authorityOf(address) {\n  const value = bareAddress(address)\n  if (!value) return ''\n  return value.includes(':') ? `[${value}]` : value\n}\n\nfunction hostMatches(host, authority) {\n  if (LOOPBACK_HOST_RE.test(host)) return true\n  return authority !== '' && (host === authority || host.startsWith(`${authority}:`))\n}\n\n/**\n * 接受来自本机、经回环地址或（可选）监听器自身绑定地址发起的请求。\n *\n * Host 栅栏是 DNS rebinding 防御：Host 取自浏览器认为自己在访问的 URL，被\n * rebound 的页面带的是攻击者域名，哪怕 socket 落在本机。带 Origin 时必须与\n * Host 同源，挡掉跨站调用。DSH 0.2.1 只绑定具体地址字面量（wildcard 在加载期\n * 被拒），所以部署可能绑 LAN IP、此时 127.0.0.1 根本不监听：`allowLocalAddress`\n * 让同一台机器经该监听器访问，判据是连接自身的本地地址（内核给出），不是请求头。\n *\n * @param req - 入站 HTTP 请求。\n * @param options.allowLocalAddress - 同时接受连接自身的绑定地址作为 peer 与\n *   Host；带副作用的端点保持默认的严格回环。\n */\nexport function localHostOk(req, { allowLocalAddress = false } = {}) {\n  const peer = req.socket?.remoteAddress\n  const local = allowLocalAddress ? bareAddress(req.socket?.localAddress) : ''\n  const sameMachine = isLoopback(peer) || (local !== '' && bareAddress(peer) === local)\n  if (!sameMachine) return false\n  const host = req.headers?.host || ''\n  if (!hostMatches(host, local === '' ? '' : authorityOf(local))) return false\n  const origin = req.headers?.origin\n  if (origin) {\n    let originHost\n    try { originHost = new URL(origin).host } catch { return false }\n    if (!originHost || originHost !== host) return false\n  }\n  return true\n}\n"
    },
    {
      "path": "src/desktop-window.js",
      "content": "/**\n * Desktop-window bridge: discover an Electron backend and spawn the pet\n * window process (src/pet-window.cjs, which loads the pet-view page).\n *\n * Electron backends, in preference order:\n *   1. DSH_PET_ELECTRON env var override.\n *   2. The bundled Electron runtime (vendor/electron-<platform>-<arch>,\n *      resolved per-platform/arch via electronArtifact, fetched on demand)\n *      — so every user (plain web DSH host included) gets the same floating\n *      window with browser-engine GIF animation.\n *   3. npm global install (`npm install -g electron`) — find via\n *      `npm prefix -g` → node_modules/electron/dist/.\n *   4. The dsh binary root (derived from process.argv[1]) →\n *      node_modules/electron/dist/ or desktop/node_modules/electron/dist/.\n *   5. cwd fallback — the profile directory's own node_modules, or a local\n *      dev checkout that has electron in its tree.\n *\n * Configuration travels via environment variables (DSH_PET_URL /\n * DSH_PET_PARENT_PID): passing extra CLI args to a spawned Electron on\n * Windows crashes with exit -1, while env is stable.\n */\n\nimport { execFileSync } from 'node:child_process'\nimport { spawn } from 'node:child_process'\nimport { existsSync } from 'node:fs'\nimport { resolve, dirname } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { runtimeTarget, electronBinaryIn, isUsableElectronRoot } from './electron-fetch.mjs'\n\nconst here = dirname(fileURLToPath(import.meta.url))\n\n/**\n * Walk up from `startDir` looking for a directory containing the given\n * `marker` path (relative to the candidate root). Returns the first\n * matching root, or `null` after `maxDepth` levels.\n */\nexport function findRoot(startDir, marker, maxDepth = 10) {\n  let dir = startDir\n  for (let i = 0; i < maxDepth; i++) {\n    if (existsSync(resolve(dir, marker))) return dir\n    const parent = dirname(dir)\n    if (parent === dir) break\n    dir = parent\n  }\n  return null\n}\n\n/**\n * Locate the dsh binary root by walking up from process.argv[1] (the main\n * script, typically `@deepseek-ai/dsh/lib/bin.js`). Falls back to cwd.\n */\nexport function findDshRoot(fallbackCwd) {\n  const argv1 = process.argv[1]\n  if (argv1) {\n    const root = findRoot(dirname(resolve(argv1)), 'package.json')\n    if (root) {\n      if (existsSync(resolve(root, 'lib', 'bin.js')) || existsSync(resolve(root, 'node_modules', '@deepseek-ai', 'dsh'))) {\n        return root\n      }\n    }\n  }\n  return fallbackCwd ?? null\n}\n\n/**\n * Try to find the npm global prefix by running `npm prefix -g`.\n * Returns the prefix path on success, null on failure.\n */\nfunction getNpmGlobalPrefix() {\n  try {\n    const out = execFileSync('npm', ['prefix', '-g'], { encoding: 'utf8', timeout: 5000, stdio: ['pipe', 'pipe', 'pipe'] }).trim()\n    return out || null\n  } catch {\n    return null\n  }\n}\n\n/**\n * Candidate Electron backends, in preference order. Platform and cwd are\n * injectable for tests.\n * @returns `[{ kind: 'electron', command, args }]`.\n */\nexport function backendCandidates({ platform = process.platform, cwd = process.cwd(), arch = process.arch } = {}) {\n  const candidates = []\n  const args = [resolve(here, 'pet-window.cjs')]\n\n  // --- 1. DSH_PET_ELECTRON env var override (highest priority) ---\n  if (process.env.DSH_PET_ELECTRON) {\n    candidates.push({ kind: 'electron', command: process.env.DSH_PET_ELECTRON, args })\n  }\n\n  // --- 2. Bundled vendor runtime (ships with the plugin, resolved per platform/arch) ---\n  // 发现候选一律做完整性校验（issue #24）：exe-only 残缺目录必须跳过，让调用方\n  // 走 ensureElectronRuntime 的自动重装，而不是永远启动残缺运行时。\n  const bundledRoot = resolve(here, '..', 'vendor', runtimeTarget(platform, arch).folder)\n  const bundled = electronBinaryIn(bundledRoot, platform, arch)\n  if (isUsableElectronRoot(bundledRoot, platform)) {\n    candidates.push({ kind: 'electron', command: bundled, args })\n  }\n\n  // --- 3. npm global install — user ran `npm install -g electron` somewhere ---\n  const npmPrefix = getNpmGlobalPrefix()\n  if (npmPrefix) {\n    const globalRoot = resolve(npmPrefix, 'node_modules', 'electron', 'dist')\n    const globalElectron = electronBinaryIn(globalRoot, platform, arch)\n    if (isUsableElectronRoot(globalRoot, platform)) {\n      candidates.push({ kind: 'electron', command: globalElectron, args })\n    }\n  }\n\n  // --- 4. dsh binary root (from process.argv[1]) — the harness or any\n  //     sibling project that happens to have electron in its node_modules ---\n  const dshRoot = findDshRoot(cwd)\n  if (dshRoot) {\n    for (const base of [\n      resolve(dshRoot, 'node_modules', 'electron', 'dist'),\n      resolve(dshRoot, 'desktop', 'node_modules', 'electron', 'dist'),\n    ]) {\n      if (isUsableElectronRoot(base, platform)) {\n        candidates.push({ kind: 'electron', command: electronBinaryIn(base, platform, arch), args })\n        break\n      }\n    }\n  }\n\n  // --- 5. cwd fallback — profile directory or local dev checkout ---\n  for (const base of [\n    resolve(cwd, 'desktop/node_modules/electron/dist'),\n    resolve(cwd, 'node_modules/electron/dist'),\n  ]) {\n    if (isUsableElectronRoot(base, platform)) {\n      candidates.push({ kind: 'electron', command: electronBinaryIn(base, platform, arch), args })\n      break\n    }\n  }\n\n  return candidates\n}\n\n/** First usable backend, or null when none is available. */\nexport function resolveBackend(options) {\n  return backendCandidates(options)[0] ?? null\n}\n\n/**\n * Manages the spawned pet window process. `start()` is a no-op when the\n * window already runs or when no backend was found (the browser pet stays\n * as the fallback). `stop()` tears the process down; `running` reflects whether\n * a window process is alive; `onExit` fires when the window dies and receives this instance.\n */\nexport class DesktopWindow {\n  constructor({\n    url,\n    webUrl,\n    backend = resolveBackend(),\n    parentPid = process.pid,\n    logger = console,\n    spawnImpl = spawn,\n    onExit,\n    posX = null,\n    posY = null,\n    rendererHeader = null,\n  } = {}) {\n    if (!url) throw new Error('DesktopWindow requires a --url')\n    this.url = url\n    this.webUrl = webUrl\n    this.backend = backend\n    this.parentPid = parentPid\n    this.logger = logger\n    this.spawnImpl = spawnImpl\n    this.onExit = onExit\n    // 可选的渲染进程准入头：仅私有/下游 DSH Desktop 构建会提供（公开 DSH 没有\n    // desktopBrowserAccess 服务）。存在时经 env 交给 pet-window.cjs 自注入到\n    // 同源请求；缺失时窗口按普通浏览器直连宿主，公开宿主本就放行。\n    this.rendererHeader = rendererHeader && typeof rendererHeader.name === 'string' && rendererHeader.name\n      && typeof rendererHeader.value === 'string' && rendererHeader.value\n      ? { name: rendererHeader.name, value: rendererHeader.value }\n      : null\n    // 上次关闭时的窗口位置（config.desktopX/desktopY）：有效坐标经 env 传给\n    // pet-window.cjs 建窗即定位。坐标与 bounds API 同空间（见 pet-window.cjs\n    // 顶部 force-device-scale-factor 注释：非 macOS 下为物理像素，macOS 为逻辑点）。\n    this.posX = Number.isFinite(Number(posX)) && posX !== null ? Number(posX) : null\n    this.posY = Number.isFinite(Number(posY)) && posY !== null ? Number(posY) : null\n    this.child = undefined\n    this.startNonce = Date.now()\n  }\n\n  get running() {\n    return this.child !== undefined && this.child.exitCode === null && !this.child.killed\n  }\n\n  start() {\n    if (this.running) return this.child\n    if (!this.backend) {\n      this.logger.info?.('dsh-pet-remielle: no Electron backend found, browser pet remains')\n      return undefined\n    }\n    const child = this.spawnImpl(this.backend.command, this.backend.args, {\n      cwd: dirname(this.backend.command),\n      // pipe 而非 inherit：Electron/Chromium 启动时常往宿主控制台写一个空行。\n      // 有内容的诊断日志仍转发；纯空白块丢掉。\n      stdio: ['ignore', 'pipe', 'pipe'],\n      windowsHide: false,\n      env: {\n        ...process.env,\n        ELECTRON_RUN_AS_NODE: undefined,\n        DSH_PET_URL: this.url + (this.url.includes('?') ? '&' : '?') + 'v=' + this.startNonce,\n        DSH_WEB_URL: this.webUrl || new URL('/', this.url).origin,\n        DSH_PET_PARENT_PID: String(this.parentPid),\n        // 上次位置持久化：仅在坐标齐全时传入，子进程据此建窗即定位。\n        ...(this.posX !== null && this.posY !== null\n          ? { DSH_PET_POS_X: String(Math.round(this.posX)), DSH_PET_POS_Y: String(Math.round(this.posY)) }\n          : {}),\n        // DSH Desktop 渲染进程准入头（可选，见构造函数注释）。\n        ...(this.rendererHeader\n          ? { DSH_PET_RENDERER_HEADER_NAME: this.rendererHeader.name, DSH_PET_RENDERER_HEADER_VALUE: this.rendererHeader.value }\n          : {}),\n      },\n    })\n    this.child = child\n    let exitNotified = false\n    const notifyExit = () => {\n      if (exitNotified) return\n      exitNotified = true\n      // 这个退出回调属于 child。宿主可能已经因为别的原因换上了新进程\n      // （用户重启桌面模式，而本进程的 exit 事件姗姗来迟），此时 this.child\n      // 指向的是**别人**。\n      //\n      // 上一版对两件事的处理不对称：this.child 的清理有 `=== child` 保护，\n      // onExit 却是无条件调用。宿主侧的 onExit 会把 desktop 引用置空，于是\n      // 「旧进程的迟到退出」抹掉了「正在跑的新进程」——宿主认为没有桌宠窗，\n      // 用户再开一次就出现两个置顶窗，外加一个失去引用的僵尸 electron 进程。\n      //\n      // 判 stale 只认「确实有另一个进程顶上」：this.child 已是 undefined 是\n      // stop() 主动停掉的正常路径，那种退出仍要通知 onExit（宿主有别处依赖\n      // 退出回调做收尾），不能一并吞掉。\n      const superseded = this.child !== undefined && this.child !== child\n      if (!superseded) this.child = undefined\n      // 退出原因必须可见：桌面窗进程死得无声会让「位置/启动类」问题完全没法\n      // 排查（DSH Desktop 宿主不转发子进程 stdio 到日志，只有这条能落盘）。\n      const code = child.exitCode\n      const signal = child.signalCode\n      this.logger.info?.(`dsh-pet-remielle: pet window exited (code=${code === null ? 'signal:' + String(signal) : code}${superseded ? ', superseded by a newer window' : ''})`)\n      if (!superseded) this.onExit?.(this)\n    }\n    const forward = (stream, dest) => {\n      if (!stream || typeof stream.on !== 'function' || !dest || typeof dest.write !== 'function') return\n      stream.on('data', (chunk) => {\n        const text = String(chunk)\n        if (!text.trim()) return\n        dest.write(text)\n      })\n    }\n    forward(child.stdout, process.stdout)\n    forward(child.stderr, process.stderr)\n    child.once('error', (error) => {\n      this.logger.error?.(`dsh-pet-remielle: pet window failed to start: ${error.message}`)\n      notifyExit()\n    })\n    child.once('exit', () => {\n      notifyExit()\n    })\n    return child\n  }\n\n  /** Stop the pet window and resolve once its process has exited (immediately\n   *  when it was not running). Callers that must release file locks before\n   *  replacing plugin files (self-update) await the returned promise. */\n  stop(reason = 'stopped') {\n    const child = this.child\n    this.child = undefined\n    if (!child || child.exitCode !== null) return Promise.resolve()\n    return new Promise((resolve) => {\n      // 兜底定时：万一 kill 失败且 exit 事件不来，也不能把更新流程卡死\n      const fallback = setTimeout(resolve, 5000)\n      if (typeof fallback.unref === 'function') fallback.unref()\n      child.once('exit', () => {\n        clearTimeout(fallback)\n        resolve()\n      })\n      try {\n        child.kill()\n      } catch (error) {\n        this.logger.warn?.(`dsh-pet-remielle: pet window kill failed (${reason}): ${String(error)}`)\n      }\n    })\n  }\n}\n"
    },
    {
      "path": "src/balance.js",
      "content": "/**\n * dsh-pet-remielle balance/usage service.\n *\n * Ported from DeepSeek-Balance-Whale-Widget (lib/index.js), adapted to the pet\n * plugin's host context:\n *   - balance from `api.deepseek.com/user/balance` (DEEPSEEK_API_KEY)\n *   - today usage in two modes:\n *       ledger (default): balance-delta ledger persisted to `$DSH_HOME/.dshp-usage.json`\n *       token:            platform usage API (DEEPSEEK_PLATFORM_TOKEN) with\n *                         peak/off-peak pricing\n *   - 25s in-memory cache + in-flight dedup + transient-failure stale fallback.\n *\n * The ledger file name is `.dshp-usage.json` (not the whale's `.dshw-usage.json`)\n * so the two plugins never fight over the same ledger.\n */\n\nimport fs from 'node:fs'\nimport os from 'node:os'\nimport path from 'node:path'\nimport { createHolidayStore } from './holidays.js'\n\nconst BALANCE_URL = 'https://api.deepseek.com/user/balance'\nconst USAGE_URL = 'https://platform.deepseek.com/api/v0/usage/by_api_key/cost'\nconst BALANCE_TTL_MS = 25000\n\nexport function normalizeUsageMode(m) {\n  return m === 'token' ? 'token' : 'ledger'\n}\n\n/**\n * `usage/by_api_key/cost` returns the platform's own cost per hour bucket\n * (`data.biz_data.data[].series[].buckets[].cost`, CNY string). Summing them\n * gives the exact today usage — no local pricing table needed.\n */\nexport function computeTodayCost(data) {\n  const biz = data && data.data && data.data.biz_data\n  const groups = biz && Array.isArray(biz.data) ? biz.data : null\n  if (!groups) return null\n  let total = 0\n  let found = false\n  for (const g of groups) {\n    const series = Array.isArray(g && g.series) ? g.series : []\n    for (const s of series) {\n      const buckets = Array.isArray(s && s.buckets) ? s.buckets : []\n      for (const b of buckets) {\n        const c = Number(b && b.cost)\n        if (!isFinite(c)) continue\n        found = true\n        total += c\n      }\n    }\n  }\n  return found ? total : null\n}\n\n/**\n * @param {object} options\n * @param {(name: string) => Promise<{value: string}|null>} options.resolveCredential\n * @param {string} [options.dshHome]\n * @param {(m: string) => void} [options.log]\n * @param {typeof fetch} [options.fetchImpl] 网络出口，测试注入用（默认全局 fetch）\n * @param {() => number} [options.now] 时钟，测试注入用（默认 Date.now）\n */\nexport function createBalanceService({ resolveCredential, getPlatformToken, dshHome, log, fetchImpl = globalThis.fetch, now = () => Date.now() }) {\n  const DSH_HOME = dshHome || process.env.DSH_HOME || path.join(os.homedir(), '.dsh')\n  const logger = log || (() => {})\n  // 峰谷时段判定（issue #25）：周末/法定节假日全天空闲，其余按 9–12、14–18\n  // 判高峰。节假日日历以内置表兜底、后台静默刷新远程数据。\n  const holidays = createHolidayStore({ dshHome: DSH_HOME, log: logger, fetchImpl, now })\n\n  const USAGE_FILE_CANDIDATES = [\n    path.join(DSH_HOME, '.dshp-usage.json'),\n    path.join(DSH_HOME, 'profiles', 'web', '.dshp-usage.json'),\n  ]\n\n  let balanceCache = null\n  let balanceInFlight = null\n\n  async function fetchBalance() {\n    let cred\n    try {\n      cred = await resolveCredential('DEEPSEEK_API_KEY')\n    } catch (err) {\n      return { ok: false, code: 'NO_KEY', error: '凭据读取失败: ' + String((err && err.message) || err).slice(0, 160) }\n    }\n    if (!cred) {\n      return { ok: false, code: 'NO_KEY', error: '未配置 DEEPSEEK_API_KEY' }\n    }\n    let lastErr = null\n    for (let attempt = 0; attempt < 2; attempt++) {\n      let res\n      try {\n        res = await fetchImpl(BALANCE_URL, {\n          headers: { Authorization: 'Bearer ' + cred.value },\n          signal: AbortSignal.timeout(20000),\n        })\n      } catch (err) {\n        lastErr = err\n        if (attempt === 0) await new Promise((r) => setTimeout(r, 500))\n        continue\n      }\n      if (!res.ok) {\n        lastErr = new Error('HTTP ' + res.status)\n        if (res.status < 500) break\n        if (attempt === 0) await new Promise((r) => setTimeout(r, 500))\n        continue\n      }\n      let data\n      try {\n        data = await res.json()\n      } catch (err) {\n        lastErr = err\n        break\n      }\n      const info = data && Array.isArray(data.balance_infos) ? data.balance_infos[0] : null\n      if (!info || info.total_balance === undefined) {\n        return { ok: false, code: 'SHAPE', error: '余额接口返回结构异常' }\n      }\n      return {\n        ok: true,\n        totalBalance: Number(info.total_balance),\n        currency: String(info.currency || 'CNY'),\n        updatedAt: new Date(now()).toISOString(),\n      }\n    }\n    const transient = !(lastErr && /^HTTP 4\\d\\d/.test(lastErr.message))\n    return {\n      ok: false,\n      code: 'HTTP',\n      transient: transient,\n      error: '余额接口请求失败: ' + String((lastErr && lastErr.message) || lastErr).slice(0, 200),\n    }\n  }\n\n  async function fetchUsage() {\n    // 优先用配置里的 platformToken（main 设置页填写），回落到 DSH 凭据服务\n    let token = ''\n    try { token = String((typeof getPlatformToken === 'function' ? getPlatformToken() : '') || '').replace(/^Bearer\\s+/i, '') } catch { /* ignore */ }\n    if (!token) {\n      let cred\n      try {\n        cred = await resolveCredential('DEEPSEEK_PLATFORM_TOKEN')\n      } catch (err) {\n        return { error: 'platform cred resolve failed' }\n      }\n      if (!cred) return { error: 'no platform token' }\n      token = String(cred.value).replace(/^Bearer\\s+/i, '')\n    }\n    try {\n      const current = new Date(now())\n      const tz = -current.getTimezoneOffset() * 60\n      const start = Math.floor(new Date(current.getFullYear(), current.getMonth(), current.getDate()).getTime() / 1000)\n      const end = start + 86400\n      const url = `${USAGE_URL}?start=${start}&end=${end}&tz=${tz}`\n      const res = await fetchImpl(url, {\n        headers: { Authorization: 'Bearer ' + token },\n        signal: AbortSignal.timeout(15000),\n      })\n      if (!res.ok) return { error: 'http ' + res.status }\n      const data = await res.json()\n      const amount = computeTodayCost(data)\n      if (isFinite(amount)) return { amount }\n      return { error: 'no usage' }\n    } catch (err) {\n      return { error: String((err && err.message) || err) }\n    }\n  }\n\n  function todayKey() {\n    const d = new Date(now())\n    const p = (n) => String(n).padStart(2, '0')\n    return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate())\n  }\n\n  function readUsageLedger() {\n    for (const p of USAGE_FILE_CANDIDATES) {\n      try {\n        const parsed = JSON.parse(fs.readFileSync(p, 'utf8'))\n        if (parsed && typeof parsed === 'object' && typeof parsed.date === 'string') return parsed\n      } catch (err) { /* try next */ }\n    }\n    return { date: todayKey(), lastBalance: null, todayUsage: 0, history: {} }\n  }\n\n  function writeUsageLedger(led) {\n    const body = JSON.stringify(led)\n    for (const p of USAGE_FILE_CANDIDATES) {\n      try {\n        fs.writeFileSync(p, body, 'utf8')\n        return true\n      } catch (err) { /* try next */ }\n    }\n    return false\n  }\n\n  /** 记账模式：每次观测到余额后，用余额正差值累计当天用量（跨天自动归零并归档）。 */\n  function recordLedgerUsage(currentBalance) {\n    const t = todayKey()\n    const led = readUsageLedger()\n    if (led.date !== t) {\n      if (led.date && typeof led.todayUsage === 'number') {\n        led.history = led.history || {}\n        led.history[led.date] = led.todayUsage\n      }\n      led.date = t\n      led.lastBalance = currentBalance\n      led.todayUsage = 0\n    } else {\n      const prev = typeof led.lastBalance === 'number' ? led.lastBalance : currentBalance\n      if (typeof prev === 'number' && typeof currentBalance === 'number' && currentBalance < prev) {\n        led.todayUsage = (typeof led.todayUsage === 'number' ? led.todayUsage : 0) + (prev - currentBalance)\n      }\n      led.lastBalance = currentBalance\n    }\n    const keys = Object.keys(led.history || {}).sort()\n    while (keys.length > 30) {\n      delete led.history[keys.shift()]\n    }\n    writeUsageLedger(led)\n    return led\n  }\n\n  async function getBalancePayload(usageMode) {\n    const payload = await fetchBalance()\n    if (!payload.ok) return payload\n    // 无论哪种模式，都先把余额观测记入账本（自动累积记账数据）\n    const led = recordLedgerUsage(Number(payload.totalBalance))\n    const mode = normalizeUsageMode(usageMode)\n    const full = { ...payload }\n    full.isPeak = holidays.isPeak(Math.floor(now() / 1000))\n    // 日历刷新属后台行为，不阻塞余额展示；失败静默（内置表兜底仍在）。\n    void holidays.refresh()\n    if (mode === 'ledger') {\n      full.todayUsage = led.todayUsage\n      full.usageMode = 'ledger'\n      return full\n    }\n    // token：尝试平台令牌实时计算\n    const u = await fetchUsage()\n    if (u && u.amount !== undefined) {\n      full.todayUsage = u.amount\n      full.usageMode = 'token'\n      return full\n    }\n    // 无令牌或令牌失败：回落记账模式\n    full.todayUsage = led.todayUsage\n    full.usageMode = 'ledger'\n    return full\n  }\n\n  async function getBalance(usageMode) {\n    const at = now()\n    if (balanceCache && at - balanceCache.at < BALANCE_TTL_MS) {\n      return balanceCache.payload\n    }\n    if (balanceInFlight) return balanceInFlight\n    balanceInFlight = getBalancePayload(usageMode)\n      .then((payload) => {\n        if (payload.ok) {\n          balanceCache = { at: now(), payload }\n          return payload\n        }\n        if (payload.transient && balanceCache) {\n          // transient network/API blip: keep serving the last known balance\n          return { ...balanceCache.payload, stale: true, error: payload.error }\n        }\n        if (!payload.transient) logger('[pet-balance]', payload.code, payload.error)\n        return payload\n      })\n      .catch((err) => ({\n        ok: false,\n        code: 'ERROR',\n        error: '余额服务异常: ' + String((err && err.message) || err).slice(0, 200),\n      }))\n      .finally(() => {\n        balanceInFlight = null\n      })\n    return balanceInFlight\n  }\n\n  /** Force the next request to recompute (e.g. when usageMode changes). */\n  function invalidate() {\n    balanceCache = null\n  }\n\n  return { getBalance, invalidate, normalizeUsageMode }\n}\n"
